-- 059_restore_private_area_spawns.sql
--
-- Companion to 058: garlemald's server_spawn_locations seed (031) — also a
-- stale project-meteor-mirror snapshot — is missing the NPC spawns that
-- populate those private areas (the man0l1 Echo barracudas/Mannskoen/
-- Totoruto/adventurers in PrivateAreaMasterPast type 3, and every other
-- quest's instanced-cutscene cast). Without them the warp target area is
-- empty and the quest cannot advance. Rows copied from project-meteor-
-- server's Data/sql/server_eventnpc_spawn_locations.sql (PRIVATE-AREA rows
-- only — privateAreaName != ''); pmeteor's motionPack maps to garlemald's
-- animationId, actorState defaults to 0, customDisplayName NULL. uniqueId
-- is kept verbatim (functionally a label; quest ENPC matching is by
-- actorClassId). MUST land with 058 so the private area exists before the
-- boot spawn-attach routes these seeds into it (an unregistered area would
-- fall them back into the public root zone). Idempotent via INSERT OR
-- IGNORE on id. (Garlemald-Server #46.)

INSERT OR IGNORE INTO "server_spawn_locations" ("id","actorClassId","uniqueId","zoneId","privateAreaName","privateAreaLevel","positionX","positionY","positionZ","rotation","actorState","animationId","customDisplayName") VALUES (1025, 1000869, 'man0l1_adventurer1', 230, 'PrivateAreaMasterPast', 3, -602.241, 43, -62.3205, 0.75078, 0, 1022, NULL);
